    if len(a) < len(b):
        a, b = b, a

    cols = len(b) + 1
    prev2 = list(range(cols))  # row i-2, initially row 0
    prev = [0] * cols
    prev[0] = 1  # row 1, dp[1][0]

    for j in range(1, cols):
        cost = 0 if a[0] == b[j - 1] else 1
        prev[j] = min(prev2[j] + 1, prev[j - 1] + 1, prev2[j - 1] + cost)

    for i in range(2, len(a) + 1):
        cur = [0] * cols
        cur[0] = i
        ai_prev = a[i - 1]
        ai_prev2 = a[i - 2]
        for j in range(1, cols):
            cost = 0 if ai_prev == b[j - 1] else 1
            cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)

            if j >= 2 and ai_prev == b[j - 2] and ai_prev2 == b[j - 1]:
                cur[j] = min(cur[j], prev2[j - 2] + 1)

        prev2, prev = prev, cur

