def edit_distance(a: str, b: str) -> int:
    """Return the optimal string alignment distance between a and b."""
    if not a:
        return len(b)
    if not b:
        return len(a)

    # OSA distance is symmetric; swap so b is the shorter string to optimize space.
    if len(a) < len(b):
        a, b = b, a

    cols = len(b) + 1
    prev2 = list(range(cols))  # row i - 2
    prev = [0] * cols          # row i - 1
    prev[0] = 1

    for j in range(1, cols):
        cost = 0 if a[0] == b[j - 1] else 1
        prev[j] = min(prev2[j] + 1, prev[j - 1] + 1, prev2[j - 1] + cost)

    for i in range(2, len(a) + 1):
        cur = [0] * cols
        cur[0] = i
        ai_prev = a[i - 1]
        ai_prev2 = a[i - 2]
        for j in range(1, cols):
            cost = 0 if ai_prev == b[j - 1] else 1
            cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)

            if j >= 2 and ai_prev == b[j - 2] and ai_prev2 == b[j - 1]:
                cur[j] = min(cur[j], prev2[j - 2] + 1)

        prev2, prev = prev, cur

    return prev[-1]
